// The handshake is a plain HTTP handler that hands off to the Upgrader.
var upgrader = websocket.Upgrader{}

func wsHandler(w http.ResponseWriter, r *http.Request) {
	// r arrives as GET with Upgrade: websocket / Sec-WebSocket-Key headers.
	conn, err := upgrader.Upgrade(w, r, nil) // writes 101 Switching Protocols
	if err != nil {
		return // upgrader already wrote an HTTP error response
	}
	defer conn.Close()
	// From here the socket speaks WebSocket frames, not HTTP.
	_, msg, _ := conn.ReadMessage()
	conn.WriteMessage(websocket.TextMessage, msg) // echo back
}

// Configure the Upgrader, then read/write typed messages on the *Conn.
var upgrader = websocket.Upgrader{
	ReadBufferSize:  1024,
	WriteBufferSize: 1024,
	CheckOrigin:     func(r *http.Request) bool { return r.Header.Get("Origin") == "https://app.example.com" },
}

func echo(w http.ResponseWriter, r *http.Request) {
	conn, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		return
	}
	defer conn.Close()
	for {
		mt, data, err := conn.ReadMessage() // mt = TextMessage or BinaryMessage
		if err != nil {
			break // client closed or protocol error
		}
		if err := conn.WriteMessage(mt, data); err != nil {
			break
		}
	}
}

// One goroutine owns writes; everyone else sends on the send channel.
type client struct {
	conn *websocket.Conn
	send chan []byte // buffered outbound queue
}

// writePump is the SOLE writer for this connection.
func (c *client) writePump() {
	defer c.conn.Close()
	for msg := range c.send { // serialized: no concurrent writes
		if err := c.conn.WriteMessage(websocket.TextMessage, msg); err != nil {
			return
		}
	}
}

// Any goroutine can enqueue safely; it never touches conn directly.
func (c *client) push(msg []byte) {
	select {
	case c.send <- msg:
	default: // drop or disconnect a slow client instead of blocking
	}
}

// A single hub goroutine owns the client set; channels serialize access.
type hub struct {
	clients    map[*client]bool
	broadcast  chan []byte
	register   chan *client
	unregister chan *client
}

func (h *hub) run() {
	for {
		select {
		case c := <-h.register:
			h.clients[c] = true
		case c := <-h.unregister:
			if _, ok := h.clients[c]; ok {
				delete(h.clients, c)
				close(c.send) // signals writePump to exit
			}
		case msg := <-h.broadcast:
			for c := range h.clients {
				select {
				case c.send <- msg:
				default: // slow client: drop it rather than block the hub
					close(c.send)
					delete(h.clients, c)
				}
			}
		}
	}
}

// Pings from the writer; pongs reset the reader's deadline.
const (
	pongWait   = 60 * time.Second
	pingPeriod = (pongWait * 9) / 10 // ping before the deadline expires
)

func (c *client) readPump() {
	c.conn.SetReadDeadline(time.Now().Add(pongWait))
	c.conn.SetPongHandler(func(string) error {
		return c.conn.SetReadDeadline(time.Now().Add(pongWait)) // extend on pong
	})
	for {
		if _, _, err := c.conn.ReadMessage(); err != nil {
			return // no pong in time -> deadline exceeded -> cleanup
		}
	}
}

func (c *client) pinger() {
	t := time.NewTicker(pingPeriod)
	defer t.Stop()
	for range t.C {
		c.conn.SetWriteDeadline(time.Now().Add(10 * time.Second))
		if err := c.conn.WriteMessage(websocket.PingMessage, nil); err != nil {
			return
		}
	}
}

// SSE: a normal HTTP response you keep open and flush per event.
func sseHandler(w http.ResponseWriter, r *http.Request) {
	flusher, ok := w.(http.Flusher)
	if !ok {
		http.Error(w, "streaming unsupported", http.StatusInternalServerError)
		return
	}
	w.Header().Set("Content-Type", "text/event-stream")
	w.Header().Set("Cache-Control", "no-cache")
	w.Header().Set("Connection", "keep-alive")

	ticker := time.NewTicker(time.Second)
	defer ticker.Stop()
	for {
		select {
		case <-r.Context().Done(): // client disconnected
			return
		case t := <-ticker.C:
			// Event framing: optional 'event:' + 'data:' + blank line.
			fmt.Fprintf(w, "event: tick\ndata: %d\n\n", t.Unix())
			flusher.Flush() // push this event immediately
		}
	}
}

