package main

import (
	"net/http"

	"github.com/gorilla/websocket"
)

var upgrader = websocket.Upgrader{CheckOrigin: func(r *http.Request) bool { return true }}

type client struct {
	hub  *hub
	conn *websocket.Conn
	send chan []byte
}

type hub struct {
	clients    map[*client]bool
	broadcast  chan []byte
	register   chan *client
	unregister chan *client
}

func (h *hub) run() {
	for {
		select {
		case c := <-h.register:
			h.clients[c] = true
		case c := <-h.unregister:
			if _, ok := h.clients[c]; ok {
				delete(h.clients, c)
				close(c.send)
			}
		case msg := <-h.broadcast:
			for c := range h.clients {
				select {
				case c.send <- msg:
				default:
					close(c.send)
					delete(h.clients, c)
				}
			}
		}
	}
}

// readPump is the SOLE reader; it forwards messages to the hub.
func (c *client) readPump() {
	defer func() { c.hub.unregister <- c; c.conn.Close() }()
	for {
		_, msg, err := c.conn.ReadMessage()
		if err != nil {
			return
		}
		c.hub.broadcast <- msg
	}
}

// writePump is the SOLE writer; it drains the send channel.
func (c *client) writePump() {
	defer c.conn.Close()
	for msg := range c.send {
		if err := c.conn.WriteMessage(websocket.TextMessage, msg); err != nil {
			return
		}
	}
}

func (h *hub) serveWS(w http.ResponseWriter, r *http.Request) {
	conn, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		return
	}
	c := &client{hub: h, conn: conn, send: make(chan []byte, 16)}
	h.register <- c
	go c.writePump() // one writer
	go c.readPump()  // one reader
}

func main() {
	h := &hub{clients: map[*client]bool{}, broadcast: make(chan []byte), register: make(chan *client), unregister: make(chan *client)}
	go h.run()
	http.HandleFunc("/ws", h.serveWS)
	http.ListenAndServe(":8080", nil)
}

package main

import (
	"fmt"
	"net/http"
	"time"
)

// events is where the app publishes updates for this stream.
func sseHandler(events <-chan string) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		flusher, ok := w.(http.Flusher)
		if !ok {
			http.Error(w, "streaming unsupported", http.StatusInternalServerError)
			return
		}
		w.Header().Set("Content-Type", "text/event-stream")
		w.Header().Set("Cache-Control", "no-cache")
		w.Header().Set("Connection", "keep-alive")

		heartbeat := time.NewTicker(15 * time.Second)
		defer heartbeat.Stop()
		id := 0
		for {
			select {
			case <-r.Context().Done():
				return // client went away; free this goroutine
			case <-heartbeat.C:
				fmt.Fprint(w, ": keep-alive\n\n") // comment line = heartbeat
				flusher.Flush()
			case ev, open := <-events:
				if !open {
					return
				}
				id++
				// id: lets EventSource resume with Last-Event-ID on reconnect.
				fmt.Fprintf(w, "id: %d\nevent: update\ndata: %s\n\n", id, ev)
				flusher.Flush()
			}
		}
	}
}

func main() {
	events := make(chan string)
	go func() {
		for i := 0; ; i++ {
			time.Sleep(2 * time.Second)
			events <- fmt.Sprintf("tick-%d", i)
		}
	}()
	http.Handle("/events", sseHandler(events))
	http.ListenAndServe(":8080", nil)
}

