package main

import (
	"context"

	"github.com/redis/go-redis/v9"
)

const channel = "chat:broadcast"

type fanout struct {
	rdb *redis.Client
	hub *hub // the local, per-instance hub from the previous example
}

// publish sends a message to ALL instances via Redis.
func (f *fanout) publish(ctx context.Context, msg []byte) error {
	return f.rdb.Publish(ctx, channel, msg).Err()
}

// subscribe receives messages from any instance and broadcasts them locally.
func (f *fanout) subscribe(ctx context.Context) {
	sub := f.rdb.Subscribe(ctx, channel)
	defer sub.Close()
	ch := sub.Channel()
	for {
		select {
		case <-ctx.Done():
			return
		case m := <-ch:
			// Deliver to clients connected to THIS instance only.
			f.hub.broadcast <- []byte(m.Payload)
		}
	}
}

// When a client sends a message, publish it instead of broadcasting locally,
// so the subscribe loop (on every instance) performs the actual local fan-out.
func (f *fanout) onClientMessage(ctx context.Context, msg []byte) {
	_ = f.publish(ctx, msg) // Redis -> every instance -> local hubs -> clients
}

