package solution

import "github.com/gorilla/websocket"

type Client struct {
	Conn *websocket.Conn
	send chan []byte
}

func NewClient(conn *websocket.Conn) *Client {
	return &Client{Conn: conn, send: make(chan []byte, 8)}
}

// writePump is the SOLE writer of Client.Conn: ranging over a channel
// serializes every write, so no two goroutines ever call WriteMessage at once.
func (c *Client) writePump() {
	defer c.Conn.Close()
	for msg := range c.send { // exits when send is closed
		if err := c.Conn.WriteMessage(websocket.TextMessage, msg); err != nil {
			return
		}
	}
}

// Send enqueues without blocking; returns false if the buffer is full so the
// caller can drop or evict a slow client instead of stalling.
func (c *Client) Send(msg []byte) bool {
	select {
	case c.send <- msg:
		return true
	default:
		return false
	}
}

