// TestWritePumpExitsOnClose verifies writePump returns when send is closed.
func TestWritePumpExitsOnClose(t *testing.T) {
	c := &Client{send: make(chan []byte)} // nil Conn: we only test the exit path
	done := make(chan struct{})
	go func() {
		defer func() { _ = recover(); close(done) }() // Conn.Close on nil may panic; fine for this check
		c.writePump()
	}()
	close(c.send)
	<-done
}

