package solution

import "strings"

// FormatSSE builds one Server-Sent Events frame. The trailing blank line
// (\n\n) is what tells the browser's EventSource the event is complete.
func FormatSSE(id, event, data string) string {
	var b strings.Builder
	if id != "" {
		b.WriteString("id: ")
		b.WriteString(id)
		b.WriteByte('\n')
	}
	if event != "" {
		b.WriteString("event: ")
		b.WriteString(event)
		b.WriteByte('\n')
	}
	b.WriteString("data: ")
	b.WriteString(data)
	b.WriteString("\n\n") // field terminator + event terminator
	return b.String()
}

