	send chan []byte // buffered outbound queue
}

// writePump is the ONLY goroutine that writes this connection.
func (c *client) writePump() {
	defer c.conn.Close()
	for msg := range c.send { // serialized: no concurrent WriteMessage
		if err := c.conn.WriteMessage(websocket.TextMessage, msg); err != nil {
