		}
	}
}

func (h *hub) serveWS(w http.ResponseWriter, r *http.Request) {
	conn, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		return
	}
	c := &client{conn: conn, send: make(chan []byte, 16)}
	h.add(c)
	go c.writePump() // the single writer
	go func() {      // the single reader
		defer h.remove(c)
		for {
			_, msg, err := conn.ReadMessage()
			if err != nil {
				return
			}
			h.broadcast(msg)
		}
	}()
}

// broadcast only ENQUEUES; the per-client writePump does the actual write.
func (h *hub) broadcast(msg []byte) {
	for _, c := range h.clients {
		select {
		case c.send <- msg:
		default: // slow client: drop rather than block or race
		}
